package com.yuegang.zhihui.user.security;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.*;import jakarta.servlet.http.*;import java.time.*;public final class UserInternalServiceVerifier{private final InternalServiceSignature signatures;public UserInternalServiceVerifier(byte[]k){signatures=new InternalServiceSignature(k,Clock.systemUTC(),Duration.ofSeconds(30));}public void verify(HttpServletRequest r){try{String service=h(r,"X-YGH-Service");Instant time=Instant.ofEpochMilli(Long.parseLong(h(r,"X-YGH-Service-Timestamp")));var m=new InternalServiceSignature.Metadata(service,r.getMethod(),r.getRequestURI(),time);if(!signatures.verify(m,h(r,"X-YGH-Service-Signature")))throw denied();}catch(Exception e){throw denied();}}private static String h(HttpServletRequest r,String n){String v=r.getHeader(n);if(v==null||v.isBlank())throw denied();return v;}private static BusinessException denied(){return new BusinessException(ErrorCode.UNAUTHENTICATED);}}
